import{_ as t,o,c as n,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"Deployment & Testing Strategy","description":"The strategy for environment isolation, GitHub Actions CI/CD, and Firebase deployments.","frontmatter":{"isInternal":true,"type":"Standard Operating Procedure","title":"Deployment & Testing Strategy","description":"The strategy for environment isolation, GitHub Actions CI/CD, and Firebase deployments.","tags":["deployment","ci-cd","testing","environments","standard-operating-procedure"]},"headers":[],"relativePath":"ops/deployment_strategy.md","filePath":"ops/deployment_strategy.md"}'),i={name:"ops/deployment_strategy.md"};function r(s,e,l,d,c,g){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="sanjeev-ai-deployment-testing-strategy" tabindex="-1">Sanjeev AI: Deployment &amp; Testing Strategy <a class="header-anchor" href="#sanjeev-ai-deployment-testing-strategy" aria-label="Permalink to &quot;Sanjeev AI: Deployment &amp; Testing Strategy&quot;">​</a></h1><p>To independently test features and safely deploy to production without breaking the live app, we need a deployment strategy that isolates environments and automates the testing process.</p><p>Given our current stack (React/Vite, Firebase, Google Cloud), the most powerful, seamless, and cost-effective framework is a combination of <strong>Firebase Environments</strong>, <strong>GitHub Actions</strong>, and <strong>Firebase Preview Channels</strong>.</p><hr><h2 id="_1-environment-isolation-the-foundation" tabindex="-1">1. Environment Isolation (The Foundation) <a class="header-anchor" href="#_1-environment-isolation-the-foundation" aria-label="Permalink to &quot;1. Environment Isolation (The Foundation)&quot;">​</a></h2><p>Instead of having one massive database where test data mixes with real user data, we create entirely separate Firebase Projects.</p><ul><li><strong>Local (The Sandbox):</strong> You use the <strong>Firebase Local Emulator Suite</strong>. This runs Firestore, Functions, and Auth entirely on your local machine so you can test code instantly without paying for cloud reads/writes.</li><li><strong>Staging (<code>sanjeev-ai-staging</code>):</strong> A cloud project that exactly mirrors Production. This is where we test complex integrations (like YouTube OAuth and Vertex AI) before users see them.</li><li><strong>Production (<code>sanjeev-ai</code>):</strong> The live app. Code only reaches here once it has survived Staging.</li></ul><h2 id="_2-the-workflow-how-it-operates-day-to-day" tabindex="-1">2. The Workflow (How it operates day-to-day) <a class="header-anchor" href="#_2-the-workflow-how-it-operates-day-to-day" aria-label="Permalink to &quot;2. The Workflow (How it operates day-to-day)&quot;">​</a></h2><p>We will adopt a simple branch-based workflow (often called GitHub Flow).</p><ol><li><strong>Develop:</strong> You create a new feature branch (e.g., <code>feature/youtube-shorts</code>). You build it locally using the Emulators.</li><li><strong>Pull Request (PR):</strong> You push the branch to GitHub and open a Pull Request.</li><li><strong>Automated CI &amp; Preview:</strong><ul><li>GitHub Actions automatically runs your linter and unit tests.</li><li><em>The Magic Trick:</em> Firebase automatically generates a <strong>Preview URL</strong> (e.g., <code>pr-12-sanjeev-ai.web.app</code>). This gives you a live, isolated link to test your new feature <em>before</em> merging it.</li></ul></li><li><strong>Merge to Staging:</strong> Once approved, the PR merges into the <code>staging</code> branch. GitHub Actions automatically deploys the frontend and backend functions to the Staging Firebase project.</li><li><strong>Promote to Prod:</strong> After final verification in Staging, you merge <code>staging</code> into <code>main</code>, which automatically deploys everything to the live users.</li></ol><h2 id="_3-the-recommended-tooling-stack" tabindex="-1">3. The Recommended Tooling Stack <a class="header-anchor" href="#_3-the-recommended-tooling-stack" aria-label="Permalink to &quot;3. The Recommended Tooling Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Category</th><th style="text-align:left;">Recommended Tool</th><th style="text-align:left;">Why it&#39;s the best choice for Sanjeev AI</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>CI/CD Pipeline</strong></td><td style="text-align:left;"><strong>GitHub Actions</strong></td><td style="text-align:left;">Native to GitHub, free for open/private repos, and officially supported by Firebase&#39;s deployment tools.</td></tr><tr><td style="text-align:left;"><strong>Unit &amp; Component Tests</strong></td><td style="text-align:left;"><strong>Vitest</strong></td><td style="text-align:left;">Since you are already using Vite for the frontend, Vitest is significantly faster and easier to configure than Jest.</td></tr><tr><td style="text-align:left;"><strong>End-to-End (E2E) Tests</strong></td><td style="text-align:left;"><strong>Playwright</strong></td><td style="text-align:left;">The modern standard. It can open a real browser, click the &quot;Generate&quot; button, wait for the AI, and verify the video was created.</td></tr><tr><td style="text-align:left;"><strong>Backend Testing</strong></td><td style="text-align:left;"><strong>Firebase Emulators</strong></td><td style="text-align:left;">Run cloud functions and database triggers locally without deploying or waiting for cloud logs.</td></tr></tbody></table><hr><h2 id="current-implementation-status" tabindex="-1">Current Implementation Status <a class="header-anchor" href="#current-implementation-status" aria-label="Permalink to &quot;Current Implementation Status&quot;">​</a></h2><p>We have successfully implemented the core CI/CD pipeline across our environments.</p><h3 id="✅-step-1-firebase-environments-completed" tabindex="-1">✅ Step 1: Firebase Environments (Completed) <a class="header-anchor" href="#✅-step-1-firebase-environments-completed" aria-label="Permalink to &quot;✅ Step 1: Firebase Environments (Completed)&quot;">​</a></h3><p>We have linked the codebase (<code>.firebaserc</code>) to two isolated projects:</p><ul><li><strong>Staging:</strong> <code>sanjeev-ai-staging</code></li><li><strong>Production:</strong> <code>sanjeev-ai</code></li><li><strong>Development:</strong> <code>gen-lang-client-0059629431</code></li></ul><h3 id="✅-step-2-github-branch-workflow-completed" tabindex="-1">✅ Step 2: GitHub Branch Workflow (Completed) <a class="header-anchor" href="#✅-step-2-github-branch-workflow-completed" aria-label="Permalink to &quot;✅ Step 2: GitHub Branch Workflow (Completed)&quot;">​</a></h3><p>We operate a strict multi-branch flow:</p><ul><li><code>feature/*</code> branches for local development.</li><li><code>staging</code> branch for staging deployments.</li><li><code>main</code> branch for production deployments.</li></ul><h3 id="✅-step-3-github-actions-ci-cd-completed" tabindex="-1">✅ Step 3: GitHub Actions CI/CD (Completed) <a class="header-anchor" href="#✅-step-3-github-actions-ci-cd-completed" aria-label="Permalink to &quot;✅ Step 3: GitHub Actions CI/CD (Completed)&quot;">​</a></h3><p>We have fully automated our deployment pipeline using three dedicated workflows:</p><ol><li><code>firebase-hosting-pull-request.yml</code>: Generates preview URLs against the staging project for any PR.</li><li><code>firebase-hosting-merge-staging.yml</code>: Deploys to <code>sanjeev-ai-staging.web.app</code> when merging to <code>staging</code>.</li><li><code>firebase-hosting-merge-prod.yml</code>: Deploys to <code>sanjeev-ai.web.app</code> when merging to <code>main</code>.</li></ol><h3 id="✅-step-4-environment-variables-completed" tabindex="-1">✅ Step 4: Environment Variables (Completed) <a class="header-anchor" href="#✅-step-4-environment-variables-completed" aria-label="Permalink to &quot;✅ Step 4: Environment Variables (Completed)&quot;">​</a></h3><p>We have restructured our <code>.env</code> files to dynamically route API keys and Auth Domains:</p><ul><li><code>.env.local</code> for local emulators.</li><li><code>.env.staging</code> for the staging environment (built via <code>npm run build:staging</code>).</li><li><code>.env.production</code> for the production environment (built via <code>npm run build</code>).</li></ul><p>Additionally, GitHub Actions securely injects Service Account JSON keys (<code>FIREBASE_SERVICE_ACCOUNT_SANJEEV_AI_STAGING</code>, <code>FIREBASE_SERVICE_ACCOUNT_SANJEEV_AI</code>) which are used by Playwright&#39;s <code>global-setup.ts</code> to mint Firebase Custom Tokens (<code>e2e-test-user</code>). This safely bypasses Google OAuth popups during CI/CD execution.</p><h3 id="✅-step-5-frontend-testing-completed" tabindex="-1">✅ Step 5: Frontend Testing (Completed) <a class="header-anchor" href="#✅-step-5-frontend-testing-completed" aria-label="Permalink to &quot;✅ Step 5: Frontend Testing (Completed)&quot;">​</a></h3><ul><li><strong>Vitest</strong> is fully implemented for unit testing utility functions and React hooks.</li><li><strong>Playwright</strong> is fully implemented for End-to-End UI testing, running against live backend environments using Custom Tokens.</li><li>The <code>tsconfig.app.json</code> has been hardened to securely exclude all <code>*.test.ts</code>, <code>*.spec.ts</code>, and <code>e2e/</code> directories from the final Vite production build.</li></ul><h3 id="⏳-pending-next-steps" tabindex="-1">⏳ Pending Next Steps <a class="header-anchor" href="#⏳-pending-next-steps" aria-label="Permalink to &quot;⏳ Pending Next Steps&quot;">​</a></h3><ul><li>Configure GitHub Branch Protection rules to mandate PR reviews before merging into <code>staging</code> or <code>main</code>.</li></ul>',32)])])}const h=t(i,[["render",r]]);export{p as __pageData,h as default};
